import{c as i,U as n,j as r,g as t,o as s,a6 as o,n as l}from"./chunks/framework.h4W4t1IS.js";const q=JSON.parse('{"title":"Patrons de conception","description":"","frontmatter":{"title":"Patrons de conception","tags":["patrons","patrons-index","all"],"status":"ready","authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"patrons/index.md","filePath":"patrons/index.md"}'),c={name:"patrons/index.md"},d={id:"frontmatter-title",tabindex:"-1"};function u(a,e,p,m,h,f){return n(),r("div",null,[t("h1",d,[s(o(a.$frontmatter.title)+" ",1),e[0]||(e[0]=t("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=l('<p>Les <strong><a href="/420-w30-sf-po2/lexique.html#patrons-de-conception" class="lexicon-link" title="Solutions réutilisables à des problèmes courants de conception logicielle, fournissant des modèles éprouvés pour structurer et organiser le code.">patrons de conception</a></strong> (<em>design patterns</em>) sont des solutions documentées s&#39;appliquant à des problèmes récurrents en programmation orientée objet. Ils constituent un vocabulaire commun permettant aux développeurs de communiquer efficacement.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Nommer les trois catégories de patrons de conception</li><li>Identifier quel patron résout quel problème</li><li>Reconnaître les patrons couverts dans ce cours</li></ul></div><h2 id="origine" tabindex="-1">Origine <a class="header-anchor" href="#origine" aria-label="Permalink to &quot;Origine&quot;">​</a></h2><p>Les patrons de conception ont été popularisés par le livre <em>Design Patterns: Elements of Reusable Object-Oriented Software</em> (1994), écrit par le « Gang of Four » (GoF) : Erich Gamma, Richard Helm, Ralph Johnson, John Vlissides.</p><h2 id="trois-categories" tabindex="-1">Trois catégories <a class="header-anchor" href="#trois-categories" aria-label="Permalink to &quot;Trois catégories&quot;">​</a></h2><h3 id="creation-creational" tabindex="-1">Création (<em>Creational</em>) <a class="header-anchor" href="#creation-creational" aria-label="Permalink to &quot;Création (_Creational_)&quot;">​</a></h3><p>Concernent la manière de créer des objets.</p><table tabindex="0"><thead><tr><th>Patron</th><th>Description</th></tr></thead><tbody><tr><td><strong><a href="/420-w30-sf-po2/lexique.html#fabrique-simple" class="lexicon-link" title="Classe dont l&#39;unique rôle est de créer des objets, centralisant le switch/if sur le type à créer. Seule classe autorisée à contenir ce genre de switch (règle G23).">Fabrique Simple</a></strong> (<em>Simple Factory</em>)*</td><td>Encapsule la création d&#39;objets dans une méthode dédiée</td></tr><tr><td>Builder</td><td>Construction d&#39;objets complexes étape par étape</td></tr><tr><td>Singleton</td><td>Une seule instance globale</td></tr></tbody></table><p>* N&#39;est pas officiellement un patron de conception, mais est suffisamment documenté dans la littérature pour être inclus</p><h3 id="structure-structural" tabindex="-1">Structure (<em>Structural</em>) <a class="header-anchor" href="#structure-structural" aria-label="Permalink to &quot;Structure (_Structural_)&quot;">​</a></h3><p>Concernent la <a href="/420-w30-sf-po2/lexique.html#composition" class="lexicon-link" title="Mécanisme qui établit une relation A_UN entre un objet composé et ses composants, auxquels il délègue les comportements qu&#39;il ne réalise pas lui-même.">composition</a> de classes et d&#39;objets.</p><table tabindex="0"><thead><tr><th>Patron</th><th>Description</th></tr></thead><tbody><tr><td><strong><a href="/420-w30-sf-po2/lexique.html#repository" class="lexicon-link" title="Patron de conception qui fournit une interface pour accéder aux données d&#39;une source de données, encapsulant la logique de persistance et permettant de séparer les préoccupations entre la couche de domaine et la couche d&#39;accès aux données.">Repository</a></strong></td><td><a href="/420-w30-sf-po2/lexique.html#abstraction" class="lexicon-link" title="Un des quatre piliers de la POO : se concentrer sur ce qu&#39;un objet fait plutôt que sur comment il le fait. Se réalise en Java par les classes abstraites et les interfaces.">Abstraction</a> de la persistance, se comporte comme une collection</td></tr><tr><td><a href="/420-w30-sf-po2/lexique.html#facade" class="lexicon-link" title="Patron de conception qui offre une interface simplifiée vers un ensemble de classes plus complexes, en cachant leurs détails à l&#39;appelant.">Facade</a></td><td><a href="/420-w30-sf-po2/lexique.html#interface" class="lexicon-link" title="Contrat qui définit un ensemble de méthodes qu&#39;une classe doit implémenter, sans fournir d&#39;implémentation concrète. Permet de définir des comportements communs pour différentes classes.">Interface</a> simplifiée vers un sous-système complexe</td></tr><tr><td>Adaptateur</td><td>Connecte deux interfaces incompatibles</td></tr></tbody></table><h3 id="comportement-behavioral" tabindex="-1">Comportement (<em>Behavioral</em>) <a class="header-anchor" href="#comportement-behavioral" aria-label="Permalink to &quot;Comportement (_Behavioral_)&quot;">​</a></h3><p>Concernent la communication et la responsabilité entre objets.</p><table tabindex="0"><thead><tr><th>Patron</th><th>Description</th></tr></thead><tbody><tr><td><strong><a href="/420-w30-sf-po2/lexique.html#strategie" class="lexicon-link" title="Patron de conception qui permet de définir une famille d&#39;algorithmes, de les encapsuler et de les rendre interchangeables, permettant ainsi de modifier le comportement d&#39;un objet à l&#39;exécution.">Stratégie</a></strong> (<em>Strategy</em>)</td><td>Algorithmes interchangeables à l&#39;exécution</td></tr><tr><td><strong><a href="/420-w30-sf-po2/lexique.html#observateur" class="lexicon-link" title="Patron de conception qui définit une dépendance unidirectionnelle entre des objets, permettant à un objet (l&#39;observateur) de surveiller les changements d&#39;un autre objet (le sujet) et d&#39;être notifié automatiquement en cas de modification.">Observateur</a></strong> (<em>Observer</em>)</td><td>Notification découplée d&#39;un état</td></tr><tr><td>Commande</td><td><a href="/420-w30-sf-po2/lexique.html#encapsulation" class="lexicon-link" title="Pilier de la POO consistant à regrouper données et comportements dans une classe tout en contrôlant l&#39;accès (private/public) pour valider, cacher l&#39;implémentation et maintenir les invariants.">Encapsulation</a> d&#39;une action</td></tr></tbody></table><h2 id="liens-avec-solid" tabindex="-1">Liens avec SOLID <a class="header-anchor" href="#liens-avec-solid" aria-label="Permalink to &quot;Liens avec SOLID&quot;">​</a></h2><p>Les patrons de conception sont des applications concrètes des principes <a href="/420-w30-sf-po2/lexique.html#solid" class="lexicon-link" title="Acronyme des cinq principes de conception objet : Responsabilité unique (S), Ouvert/fermé (O), Substitution de Liskov (L), Ségrégation des interfaces (I), Inversion des dépendances (D).">SOLID</a> :</p><table tabindex="0"><thead><tr><th>Patron</th><th>Principes SOLID appliqués</th></tr></thead><tbody><tr><td>Stratégie</td><td><a href="/420-w30-sf-po2/lexique.html#ouvert-ferme" class="lexicon-link" title="Principe SOLID qui stipule qu&#39;une entité logicielle (classe, module, fonction) doit être ouverte à l&#39;extension mais fermée à la modification.">OCP</a>, <a href="/420-w30-sf-po2/lexique.html#inversion-des-dependances" class="lexicon-link" title="Principe SOLID qui stipule de dépendre des abstractions (interfaces) plutôt que des implémentations concrètes, autant pour les modules de haut niveau que de bas niveau.">DIP</a></td></tr><tr><td>Fabrique Simple</td><td><a href="/420-w30-sf-po2/lexique.html#responsabilite-unique" class="lexicon-link" title="Principe SOLID qui stipule qu&#39;une classe ne devrait avoir qu&#39;une seule raison de changer.">SRP</a>, OCP</td></tr><tr><td>Observateur</td><td>SRP, OCP, <a href="/420-w30-sf-po2/lexique.html#segregation-des-interfaces" class="lexicon-link" title="Principe SOLID qui stipule qu&#39;une classe ne doit pas être forcée d&#39;implémenter des interfaces qu&#39;elle n&#39;utilise pas, favorisant ainsi la création d&#39;interfaces spécifiques plutôt que générales.">ISP</a>, DIP</td></tr><tr><td>Repository</td><td>SRP, OCP, DIP</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">À retenir</p><p>Un patron de conception n&#39;est pas un module à copier-coller. C&#39;est une idée à adapter au contexte. La compréhension du <em>pourquoi</em> est plus importante que la mémorisation de la structure exacte.</p></div>',20))])}const x=i(c,[["render",u]]);export{q as __pageData,x as default};
